//! MP3 format constructor, generated by [`impl_audio_handler!`].
//!
//! [`impl_audio_handler!`]: super::macros::impl_audio_handler

use super::macros::impl_audio_handler;

impl_audio_handler! {
    format_id = "elide.audio.mp3",
    audio_format = crate::modality::AudioFormat::Mp3,
    extensions = ["mp3"],
    content_types = ["audio/mpeg"],
}

#[cfg(test)]
mod tests {
    use elide_codec::DocumentPart;
    use elide_codec::content::ContentData;
    use elide_core::modality::StreamDataReader as _;
    use elide_core::redaction::{Disposition, HiddenContentPolicy};

    use super::*;
    use crate::fixtures;
    use crate::modality::Audio;

    /// `bytes` behind an ID3v2.3 tag naming an artist.
    fn with_artist(bytes: &[u8]) -> Vec<u8> {
        let frame = b"TPE1\x00\x00\x00\x07\x00\x00\x00Jane R";
        let mut out = b"ID3\x03\x00\x00\x00\x00\x00".to_vec();
        out.push(frame.len() as u8);
        out.extend_from_slice(frame);
        out.extend_from_slice(bytes);
        out
    }

    fn contains(haystack: &[u8], needle: &[u8]) -> bool {
        haystack.windows(needle.len()).any(|w| w == needle)
    }

    #[tokio::test]
    async fn stream_reports_a_duration() {
        let mut doc = format()
            .decode(
                ContentData::new(fixtures::mp3_tone(1)),
                HiddenContentPolicy::default(),
            )
            .await
            .expect("decode");
        let DocumentPart::Stream { handle, .. } = &mut doc.parts_mut()[0] else {
            panic!("a clip is one stream")
        };
        let chunks = handle.downcast_mut::<Audio>().unwrap().chunks().unwrap();
        assert_eq!(chunks.len(), 1);
        assert_eq!(chunks[0].location.span.start_millis(), 0);
        assert!(
            chunks[0].location.span.end_millis() > 0,
            "duration should be positive"
        );
    }

    #[tokio::test]
    async fn redact_strips_the_id3_tag_it_cannot_surface() {
        let policy = HiddenContentPolicy::default().with_metadata(Disposition::ScanAsContent);
        let doc = format()
            .decode(
                ContentData::from(with_artist(&fixtures::mp3_tone(1))),
                policy,
            )
            .await
            .expect("decode");
        assert!(doc.changed_at_decode());
        let out = doc.encode().expect("encode");
        assert!(!contains(out.as_bytes(), b"Jane R"));
    }
}
